import{_ as t,o as r,c as p,a8 as e}from"./chunks/framework.BWjTbCIc.js";const d=JSON.parse('{"title":"香港管理专业协会李国宝中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-e3066ec0","school_zh":"香港管理专业协会李国宝中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"香港管理专业协会李国宝中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-LKP-FIRST","C2223-LKP-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-e3066ec0/s1/2022-23-interview.md","filePath":"reports/school-e3066ec0/s1/2022-23-interview.md"}'),s={name:"reports/school-e3066ec0/s1/2022-23-interview.md"};function n(a,o,g,c,l,i){return r(),p("div",null,[...o[0]||(o[0]=[e('<h1 id="香港管理专业协会李国宝中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">香港管理专业协会李国宝中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#香港管理专业协会李国宝中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;香港管理专业协会李国宝中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-e3066ec0">← 返回香港管理专业协会李国宝中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-lkp-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-lkp-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-lkp-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>机考后抽题短讲</strong></p><p>先用iPad或电脑完成中英数常选择题，多份为15分钟30题，也有25题的回忆；再到另一房间轮流抽题，通常无准备时间、每人不超过一分钟。机考房约30人，短讲组有11人、15人或25至30人的不同安排；同组入场不等于共同讨论。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>古诗、文言与词语</strong></p><p>题目包括古诗、文言文、四字词语、成语及修辞，按小学阶段所学作答。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读与语法</strong></p><p>阅读理解及动词时态选择题。</p></blockquote><blockquote><p><strong>数学：</strong> 中文及英语题均有</p><p><strong>心算与统计图</strong></p><p>四则运算、小数乘除、方程、百分率、最小公倍数，以及棒形图、折线图等。</p></blockquote><blockquote><p><strong>常识与时事：</strong> 语言未注明</p><p><strong>香港地理与历史</strong></p><p>大帽山位于哪个地区，或不属于哪个地区；香港低地分布；香港最大的岛屿，选项包括大屿山、坪洲、南丫岛；1842年签订什么条约。</p><p><strong>公共事务</strong></p><p>当时行政长官、财政司司长及律政司司长是谁；谁有权修改基本法；基本法第108条涉及什么税制；香港特别行政区英文简称；下一届冬奥会在哪一年举行。以上为当年题目，涉及“现任”“下一届”的答案随时间变化。</p></blockquote><blockquote><p><strong>即场表达：</strong> 粤语、普通话或英语；多份允许自选</p><p><strong>抽题与一分钟表达</strong></p><p>题目包括自我介绍、介绍学校、喜欢的食物、人物、地点、书、物件、颜色或车型；最喜欢的课外活动、与谁在哪里参加；旅行经历及会否再去、宠物、兴趣和新年愿望。另有先英语自我介绍、再用中文回答抽题的版本。</p></blockquote><h2 id="record-c2223-lkp-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-lkp-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-lkp-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 粤语、普通话及英语，按任务区分</p><p><strong>学生语言评估后家庭面谈</strong></p><p>先评估学生中英文，再见学生及家长；语言部分有四至五人同组、两位老师轮流提问的版本，学生阅读材料可能各不相同。部分学生语言环节约20分钟，家庭面谈约15分钟；另有家庭环节20至25分钟。全程一份记约45分钟。</p><p><strong>家庭环节计时与追问</strong></p><p>一个15分钟版本分九分钟问学生、六分钟问家长。通常先自我介绍后延伸，但也有无需自我介绍的场次；问题会随回答继续追问。</p></blockquote><blockquote><p><strong>语文：</strong> 中文问答，另有普通话朗读</p><p><strong>阅读与成语</strong></p><p>文章包括环保主题，阅读后回答内容分析或开放题，并谈环保方法。解释四字成语并造句，例如“广为人知”“怒气冲冲”。普通话朗读一句、两句或一小段。另有分享义工经历的题目。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>看图表达</strong></p><p>有两幅图选较喜欢的一幅并解释、约一分钟看图说故事、描述画面及所得启发等。主题包括阅读和捡垃圾，捡垃圾一组有三幅图。</p><p><strong>阅读及延伸</strong></p><p>另有英文文章阅读，问阅读是否重要；课余选择看书还是打游戏，阅读能增长哪些知识。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 中文或英语，按场次及问题不同</p><p><strong>学科学习与时间安排</strong></p><p>喜欢和不喜欢的科目、缺乏信心的学科及改善办法、如何学英语和复习、不懂功课怎么办、是否补习及其好坏、网课如何避免分心。描述放学至睡觉的安排，老师可能反复问“然后呢”；还会谈假期、兴趣班与繁忙中学生活怎样平衡，及更喜欢家长安排还是自主学习。</p><p><strong>活动与校园经历</strong></p><p>喜欢篮球、跆拳道、IT或辩论的原因及收获，学习多久、与谁参加、具体做什么、是否有压力，以前参加过哪些活动；小学六年的收获、难忘或困难经历及解决方法、帮助老师的经历。担任领袖生时怎样处理同学犯错、会否尴尬。</p><p><strong>阅读、电影与新闻</strong></p><p>介绍中英文书、角色及推荐理由；复述近期电影并说明主题；分享本地或国际新闻及反思、何时解除口罩令较合适；介绍感兴趣的名胜古迹或崇拜的人。</p><p><strong>家庭与同伴</strong></p><p>最好的朋友、怎样相处、有无兄弟姐妹、平日与父母做什么、农历新年怎样过、是否做家务、怎样照顾宠物。还会按小学经历问从男校转男女校的适应，以及与非华语同学交流的语言、内容和不同口音的适应。</p><p><strong>开放假设与自我认识</strong></p><p>用动物或颜色形容自己；有超能力会选什么，对自己及世界的好处、潜在坏处；若获一张机票想到哪里及原因；有5000元会如何使用；若当校长想改变什么、安排哪些活动或新增什么科目；将来的志愿及实践方法。</p><p><strong>择校与期望</strong></p><p>为什么选择李国宝、是否参加开放日及感受、对入学和中学生活的期望，以及有什么问题想问学校。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>孩子性格与成长支持</strong></p><p>用一至两个词或形容词描述孩子并解释；有版本父母分别回答。谈优点和待改善处、家庭角色、谁照顾日常生活和跟进复习、学习困难如何帮助、孩子温习会否闹情绪、怎样准备呈分试，以及兴趣班是否孩子喜欢。</p><p><strong>家庭生活与学校配合</strong></p><p>周末和假期活动、时间安排、如何培养阅读习惯、有无家教会经验、对未来成长的打算和期望、怎样看孩子提出的学习计划。家长也会被问选择学校的原因、学校印象、是否介意较多非华语学生、与非华语家长交流及对英语沟通的看法，最后可向学校提问。</p></blockquote><blockquote><p><strong>家长反馈：</strong></p><p><strong>互动方式</strong></p><p>有家长发现问题会紧接学生先前的回答，因此需要仔细聆听，也让孩子独立回答。一次面谈中，老师由放学后的安排持续追问至睡觉，着重了解实际生活过程。</p></blockquote>',25)])])}const k=t(s,[["render",n]]);export{d as __pageData,k as default};
